/**
 * The tarball sources of `check:strict-consumer`.
 *
 *   node scripts/strict-consumer/run.mjs                          # packages/*\/dist (default)
 *   node scripts/strict-consumer/run.mjs --packed                 # `pnpm pack:release` of this checkout
 *   node scripts/strict-consumer/run.mjs --from-registry <tag|v>  # `npm pack @comvi/<pkg>@<tag|v>`
 *
 * The default links the workspace packages, so it checks `dist/` as built but
 * not the bytes a user installs. The two tarball modes extract each `@comvi/*`
 * tarball into a pnpm-shaped store, so the declaration is generated by the
 * PACKED `@comvi/vite-plugin` and type-checked against the PACKED `.d.ts`:
 *
 *   <store>/<scope-name>/node_modules/<name>/        the extracted package
 *   <store>/<scope-name>/node_modules/<dep>          a link to each dependency
 *
 * A package's dependencies resolve from its own `node_modules`, exactly one
 * link per package, so `@comvi/core` reached directly and reached through
 * `@comvi/react` is one realpath (one TypeScript module), and the app root
 * still reaches only what it declares.
 *
 * Third-party dependencies (`react`, `vue`, `@nuxt/kit`, `vite`, …) are not
 * Comvi bytes; they link to the copy this checkout's install already has, the
 * same copy the default mode type-checks against.
 */

import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

import { registrySpec } from "../docs-quickstart/registry.mjs";

/** `{ source: "dist" | "packed" | "registry", spec }` from the command line. */
export function parseArgs(argv) {
  const options = { source: "dist", spec: null };
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === "--packed") options.source = "packed";
    else if (arg === "--from-registry") {
      options.source = "registry";
      options.spec = registrySpec(argv, ++index);
    } else throw new Error(`unknown argument "${arg}"`);
  }
  if (argv.includes("--packed") && argv.includes("--from-registry")) {
    throw new Error("--packed and --from-registry are two sources; pass one");
  }
  return options;
}

/** The file an ESM `import` of `subpath` loads, from a manifest's `exports`. */
export function importTarget(manifest, subpath = ".") {
  let entry = manifest.exports;
  if (entry && typeof entry === "object" && Object.keys(entry).some((key) => key.startsWith("."))) {
    entry = entry[subpath];
  } else if (subpath !== ".") {
    entry = undefined;
  }
  // A conditions object: the first of `import`, `default` that is present, nested or not.
  while (entry && typeof entry === "object") entry = entry.import ?? entry.default;
  if (typeof entry === "string") return entry;
  if (subpath === "." && typeof manifest.module === "string") return manifest.module;
  if (subpath === "." && typeof manifest.main === "string") return manifest.main;
  throw new Error(`${manifest.name} has no import target for "${subpath}"`);
}

const bare = (name) => name.replace(/^@/, "").replace("/", "-");

/** Where a dependency `dep` of `owner` is in this checkout's install, or `null`. */
export function workspaceResolver(repoRoot) {
  return (dep, owner) => {
    const candidates = [
      path.join(repoRoot, "packages", owner.replace(/^@comvi\//, ""), "node_modules", dep),
      path.join(repoRoot, "node_modules", dep),
      path.join(repoRoot, "node_modules", ".pnpm", "node_modules", dep),
    ];
    const found = candidates.find((candidate) =>
      fs.existsSync(path.join(candidate, "package.json")),
    );
    return found ? fs.realpathSync(found) : null;
  };
}

/**
 * Extract `tarballs` (`[{ name, file }]`) into a strict store under `root`.
 *
 * Returns `{ dirs, manifests, unresolved }`: the extracted package directory
 * and manifest per name, and the third-party dependencies `resolveThirdParty`
 * could not place (`owner -> dep`), which the caller reports.
 */
export function buildStore(tarballs, root, { resolveThirdParty }) {
  const dirs = new Map();
  const manifests = new Map();
  for (const { name, file } of tarballs) {
    const dir = path.join(root, bare(name), "node_modules", ...name.split("/"));
    fs.mkdirSync(dir, { recursive: true });
    execFileSync("tar", ["-xzf", file, "-C", dir, "--strip-components=1"]);
    const manifest = JSON.parse(fs.readFileSync(path.join(dir, "package.json"), "utf8"));
    if (manifest.name !== name) throw new Error(`${file} holds ${manifest.name}, not ${name}`);
    dirs.set(name, dir);
    manifests.set(name, manifest);
  }

  const unresolved = [];
  for (const [name, manifest] of manifests) {
    const deps = new Set([
      ...Object.keys(manifest.dependencies ?? {}),
      ...Object.keys(manifest.peerDependencies ?? {}),
    ]);
    for (const dep of [...deps].sort()) {
      const target =
        dirs.get(dep) ?? (dep.startsWith("@comvi/") ? null : resolveThirdParty(dep, name));
      if (!target) {
        if (dep.startsWith("@comvi/")) {
          throw new Error(`${name} depends on ${dep}, which is not among the tarballs`);
        }
        unresolved.push(`${name} -> ${dep}`);
        continue;
      }
      const linkPath = path.join(root, bare(name), "node_modules", ...dep.split("/"));
      fs.mkdirSync(path.dirname(linkPath), { recursive: true });
      fs.symlinkSync(target, linkPath, "junction");
    }
  }
  return { dirs, manifests, unresolved };
}
